{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "A near-real-time relay to monitoring stations on the ground would allow marine and conservation scientists to more accurately predict and react to coral bleaching events."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required. This also just allows for simplicity in communications, reduces cost, and requires less time to build and launch."
        }
      ],
      "reasoning": "The Great Barrier Reef monitoring mission and its environmental rationale are explained in detail, and the single-spacecraft choice is justified. Marine and conservation scientists are identified as users, but the responsible operator and specific customer organisations are not clearly named."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 87.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost twenty minutes was achieved, in addition to the already frequent amount of passes."
        }
      ],
      "reasoning": "The report covers launch, orbit, ground access, mission duration and disposal, and includes STK imagery and access results. However, major orbital-element errors undermine the central design; the ground-station communications claim is not adequately substantiated, and no STK project files are provided. The work shows some design understanding but is not a reliable, comprehensive mission design."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "Thus, launch may need to be adjusted if the rocket is still not constructed by the proposed date."
        }
      ],
      "reasoning": "The conclusion summarises the proposed launch, orbit and ground facility, and acknowledges a launch-vehicle risk. It is mostly a recap, however, and its positive conclusions are not well supported given the orbit calculation errors and limited evidence for imaging and communications performance."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Bibliography",
          "quote": "[6] https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        }
      ],
      "reasoning": "The report has a logical structure, contents list, executive summary, headings, figures, and bibliography. Presentation is not fully professional: prose and formatting are inconsistent, figures and tables lack clear numbering, references are incomplete, and Wikipedia is used despite the task excluding it as an acceptable source."
    }
  ],
